<script setup lang="ts">
import { onMounted,onUnmounted,ref } from 'vue'
import { ElButton,ElSelect,ElOption,ElInput,ElTag,ElDialog,ElCheckbox,ElAlert } from 'element-plus'
import { API } from '../../../shared/api'
import { dateLabel,isCancelled } from '../../../shared/console'
const props=defineProps<{api:API}>();const emit=defineEmits<{changed:[]}>()
const rows=ref<any[]>([]),status=ref('pending'),selected=ref<any>(null),source=ref<any>(null),error=ref(''),busy=ref(false),confirm=ref(false),checked=ref(false),action=ref('approve')
let alive=true
async function load(){busy.value=true;try{rows.value=await props.api.request('/memory-reviews?limit=500&status='+status.value,undefined,'GET','review-list')}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}finally{if(alive)busy.value=false}}
async function inspect(item:any){selected.value={...item};source.value=null;checked.value=false;try{const result=await props.api.request('/claim-source/'+encodeURIComponent(item.source_ref),undefined,'GET','review-source');if(alive&&selected.value?.id===item.id)source.value=result}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}}
function propose(kind:string){action.value=kind;checked.value=false;confirm.value=true}
async function apply(){if(!checked.value||!selected.value)return;busy.value=true;try{const item=selected.value;if(action.value==='approve'&&!source.value?.personal_claim_eligible)throw new Error('请先核对可用的本人来源');await props.api.request('/memory-reviews/'+encodeURIComponent(item.id)+'/'+action.value,action.value==='approve'?{content:item.content,kind:item.kind,importance:item.importance}:{});confirm.value=false;selected.value=null;source.value=null;await load();emit('changed')}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}finally{if(alive)busy.value=false}}
onMounted(()=>void load());onUnmounted(()=>{alive=false})
</script>
<template><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="explorer-grid"><section class="panel"><div class="section-title"><h2>记忆候选</h2><el-button :loading="busy" @click="load">刷新</el-button></div><el-select v-model="status" @change="load" aria-label="候选状态"><el-option value="pending" label="待审核"/><el-option value="approved" label="已批准"/><el-option value="rejected" label="已拒绝"/><el-option value="all" label="全部记录"/></el-select><p>最多载入500条。批准前请核对原文与候选含义。</p><button v-for="item in rows" :key="item.id" class="claim-row" :class="{chosen:selected?.id===item.id}" @click="inspect(item)"><div><span>{{ item.kind }}</span><el-tag size="small">{{ item.status }}</el-tag></div><strong>{{ item.content }}</strong><small>{{ dateLabel(item.created_at,true) }}</small></button><div v-if="!rows.length" class="empty"><h3>没有符合条件的候选</h3><p>不会为填充页面生成模拟记忆。</p></div></section><section class="panel"><template v-if="selected"><div class="section-title"><h2>核对与处理</h2><el-tag>{{ selected.status }}</el-tag></div><el-input v-model="selected.content" type="textarea" :rows="4" maxlength="4000" :disabled="selected.status!=='pending'"/><h3>对应原始来源</h3><div v-if="source" class="source-original">{{ source.content }}</div><p v-else>读取来源中，或来源已不可用。</p><el-alert v-if="source&&!source.personal_claim_eligible" title="该原话不能作为本人记忆依据，不能从此界面批准。" type="warning" :closable="false"/><div v-if="selected.status==='pending'" class="actions"><el-button type="primary" :disabled="busy||!source?.personal_claim_eligible" @click="propose('approve')">核对后写入长期记忆</el-button><el-button :disabled="busy" @click="propose('reject')">拒绝候选</el-button></div><p>批准会写入记忆并建立索引，可能调用已配置的Embedding服务；不会自动批准结构化Claim。</p></template><div v-else class="empty"><h3>选择一个候选查看原话</h3><p>候选文本与原始证据并排核对，审核决定由你明确执行。</p></div></section></div><el-dialog v-model="confirm" :title="action==='approve'?'确认写入长期记忆':'确认拒绝候选'" width="440px"><p>{{ selected?.content }}</p><el-checkbox v-model="checked">我已核对原话，确认执行此操作</el-checkbox><template #footer><el-button @click="confirm=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!checked" @click="apply">确认处理</el-button></template></el-dialog></template>
